-- 第二批内容题库：每个分类扩充到 10 题，共 60 题。所有题目均包含答案、解析、标签和内容版本。
INSERT INTO practice_questions VALUES
('q-gen-04','cat-general','SINGLE','MEDIUM','回答“你最大的缺点是什么”时，更合适的方式是？','["声称自己没有缺点","选择与岗位无关的玩笑缺点","说明真实但可改善的短板、影响和改进行动","批评上一家公司"]','["说明真实但可改善的短板、影响和改进行动"]','有效回答既不回避问题，也不自我否定，应展示自我认知和已经采取的改进行动。','["自我认知","表达"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-gen-05','cat-general','MULTIPLE','MEDIUM','描述项目成果时，哪些证据更有说服力？','["明确的业务指标变化","个人承担的关键行动","可核验的时间和范围","只说大家都很满意","与目标岗位的关联"]','["明确的业务指标变化","个人承担的关键行动","可核验的时间和范围","与目标岗位的关联"]','成果证据需要说明个人贡献、影响范围、量化结果以及与岗位能力的映射。','["成果量化","证据"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-gen-06','cat-general','TRUE_FALSE','EASY','为了提高通过率，可以把团队共同完成的成果全部写成个人独立完成。','["正确","错误"]','["错误"]','夸大个人贡献会造成诚信风险，应准确区分个人行动、团队协作和最终结果。','["诚信","简历"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-gen-07','cat-general','SCENARIO','MEDIUM','面试官询问期望薪资，但你还不了解岗位完整范围，最合适的是？','["拒绝回答并结束面试","先确认职责、级别和整体薪酬结构，再给出基于市场与自身能力的合理区间","随口报一个极低数字","反问面试官工资"]','["先确认职责、级别和整体薪酬结构，再给出基于市场与自身能力的合理区间"]','薪资沟通应基于职责范围、级别、市场数据和整体回报，以区间和依据进行专业协商。','["薪资沟通","谈判"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-gen-08','cat-general','SINGLE','MEDIUM','遇到完全不了解的技术问题时，最佳回答策略是？','["编造一个确定答案","只说不知道","说明已知边界、提出假设并给出验证步骤","转移到个人爱好"]','["说明已知边界、提出假设并给出验证步骤"]','面试也在评估解决未知问题的过程，清晰的边界、假设和验证路径比猜测更可靠。','["问题解决","事实边界"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-gen-09','cat-general','MULTIPLE','MEDIUM','面试结束时，适合向面试官了解哪些问题？','["岗位前三个月的成功标准","团队当前最重要的挑战","协作方式和反馈机制","询问可在官网找到的公司名称","后续流程和时间"]','["岗位前三个月的成功标准","团队当前最重要的挑战","协作方式和反馈机制","后续流程和时间"]','高质量反问帮助双方确认目标、挑战、协作和流程，也能体现候选人的准备程度。','["反向提问","岗位判断"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-gen-10','cat-general','TRUE_FALSE','MEDIUM','STAR 回答中，“行动”部分应重点说明候选人本人做了什么以及为什么这样做。','["正确","错误"]','["正确"]','行动是区分个人能力与团队背景的核心，需要说明关键决策、取舍和本人贡献。','["STAR","个人贡献"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),

('q-java-04','cat-java','SINGLE','MEDIUM','Spring 声明式事务通常在哪种调用场景下可能因代理未生效而失效？','["外部 Bean 调用公开事务方法","同一个对象内部直接调用事务方法","通过接口调用代理对象","事务方法抛出运行时异常"]','["同一个对象内部直接调用事务方法"]','默认代理模式依赖调用经过代理对象，同类内部自调用通常不会触发事务拦截器。','["Spring","事务"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-java-05','cat-java','MULTIPLE','HARD','排查 JVM 频繁 Full GC 时应重点观察哪些信息？','["堆各区域使用变化","对象晋升和分配速率","GC 日志与停顿时间","线程栈和内存泄漏路径","IDE 主题颜色"]','["堆各区域使用变化","对象晋升和分配速率","GC 日志与停顿时间","线程栈和内存泄漏路径"]','需要结合内存分布、分配速率、回收效果、停顿和对象引用链判断容量问题或泄漏。','["JVM","GC"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-java-06','cat-java','TRUE_FALSE','MEDIUM','线程池队列设置得越大，系统在高峰流量下就一定越稳定。','["正确","错误"]','["错误"]','过大的队列会隐藏过载并放大延迟和内存风险，需要结合吞吐、超时、拒绝和降级策略设计。','["并发","线程池"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-java-07','cat-java','SCENARIO','HARD','支付接口因客户端超时被重复调用，服务端应优先采用什么设计避免重复扣款？','["延长所有请求超时","基于业务幂等键建立唯一约束并返回第一次处理结果","随机忽略一半请求","关闭重试"]','["基于业务幂等键建立唯一约束并返回第一次处理结果"]','支付等关键写操作需要业务幂等键、原子状态变更和唯一约束共同保证重复请求只产生一次结果。','["幂等","支付"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-java-08','cat-java','MULTIPLE','MEDIUM','使用消息队列实现最终一致性时，需要考虑哪些机制？','["生产端可靠投递","消费者幂等","失败重试与死信","消息监控和补偿","假设消息永不重复"]','["生产端可靠投递","消费者幂等","失败重试与死信","消息监控和补偿"]','消息系统通常提供至少一次投递，业务侧仍需处理重复、失败、积压和人工补偿。','["消息队列","一致性"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-java-09','cat-java','SINGLE','MEDIUM','保护面向公网的业务 API，以下哪组措施更完整？','["只隐藏接口地址","身份认证、对象级授权、限流、输入校验和审计","只检查 User-Agent","把错误堆栈直接返回前端"]','["身份认证、对象级授权、限流、输入校验和审计"]','API 安全需要覆盖身份、资源权限、滥用防护、数据边界和可追溯性，而不是依赖地址隐藏。','["API安全","鉴权"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-java-10','cat-java','TRUE_FALSE','MEDIUM','联合索引 (a,b,c) 在所有查询条件组合下都能同等有效地使用。','["正确","错误"]','["错误"]','联合索引通常受最左前缀、范围条件、选择性和优化器判断影响，必须结合实际查询和执行计划验证。','["MySQL","索引"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),

('q-front-04','cat-frontend','SINGLE','MEDIUM','浏览器事件循环中，Promise 回调通常属于哪类任务？','["宏任务","微任务","渲染任务","网络线程"]','["微任务"]','当前宏任务结束后，浏览器会在进入下一宏任务前清空微任务队列。','["JavaScript","事件循环"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-front-05','cat-frontend','MULTIPLE','HARD','降低前端 XSS 风险的有效措施包括？','["对不可信内容按上下文编码","避免直接注入 HTML","配置严格 CSP","依赖前端隐藏字段","使用经过审核的清洗库"]','["对不可信内容按上下文编码","避免直接注入 HTML","配置严格 CSP","使用经过审核的清洗库"]','XSS 防护需要输出编码、安全 DOM API、内容清洗和 CSP 等多层防御，隐藏字段不是安全边界。','["安全","XSS"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-front-06','cat-frontend','TRUE_FALSE','MEDIUM','Core Web Vitals 只需要在开发者本机测试一次，不需要关注真实用户数据。','["正确","错误"]','["错误"]','实验室数据便于定位，真实用户监控反映不同设备和网络下的实际体验，两者需要结合。','["性能","监控"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-front-07','cat-frontend','SCENARIO','HARD','新版本上线后部分用户白屏，最优先的处置是？','["等待用户刷新","按监控影响快速回滚或关闭开关，再结合错误堆栈、版本和设备定位","删除 source map","重写整个项目"]','["按监控影响快速回滚或关闭开关，再结合错误堆栈、版本和设备定位"]','先止损并保留现场证据，再按版本、浏览器、资源加载和运行时错误逐层定位。','["稳定性","故障处理"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-front-08','cat-frontend','MULTIPLE','MEDIUM','一个可维护的前端状态设计通常应做到？','["区分服务端状态与本地 UI 状态","保持单一可信来源","派生数据优先计算而非重复存储","所有变量放到全局","明确异步加载和错误状态"]','["区分服务端状态与本地 UI 状态","保持单一可信来源","派生数据优先计算而非重复存储","明确异步加载和错误状态"]','合理分层和单一来源能减少同步问题，同时必须显式表达加载、成功和失败状态。','["状态管理","架构"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-front-09','cat-frontend','SINGLE','MEDIUM','列表渲染时稳定且唯一的 key 主要用于？','["改变字体颜色","帮助虚拟 DOM 正确识别节点身份和复用关系","加密数据","发送网络请求"]','["帮助虚拟 DOM 正确识别节点身份和复用关系"]','稳定 key 让框架在增删排序时正确匹配节点，避免状态错位和不必要重建。','["Vue","渲染"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-front-10','cat-frontend','MULTIPLE','MEDIUM','前端自动化测试体系通常可以包含？','["纯函数单元测试","组件交互测试","关键流程端到端测试","可访问性检查","只依赖人工口头确认"]','["纯函数单元测试","组件交互测试","关键流程端到端测试","可访问性检查"]','不同层级测试覆盖逻辑、组件和真实用户路径，关键流程还需要浏览器和可访问性验证。','["测试","质量"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),

('q-prod-04','cat-product','SINGLE','MEDIUM','定义 MVP 的核心目的是什么？','["一次性交付全部设想","用最小可行方案验证关键假设并获得反馈","只做视觉稿","尽量减少研发沟通"]','["用最小可行方案验证关键假设并获得反馈"]','MVP 的最小是围绕关键价值和风险，不是随意删减质量；目标是低成本获得有效学习。','["MVP","产品验证"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-prod-05','cat-product','MULTIPLE','MEDIUM','进行需求优先级判断时，应综合考虑？','["用户价值与覆盖面","业务目标","实现成本与风险","证据可信度","提出者职位高低作为唯一标准"]','["用户价值与覆盖面","业务目标","实现成本与风险","证据可信度"]','优先级应基于目标、价值、成本、风险和证据，不能只由声音大小决定。','["优先级","决策"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-prod-06','cat-product','TRUE_FALSE','MEDIUM','A/B 实验只要实验组指标上涨，就可以忽略样本量、显著性和护栏指标。','["正确","错误"]','["错误"]','需要验证样本、随机化、统计置信和护栏指标，避免把随机波动或副作用当成有效提升。','["AB实验","数据"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-prod-07','cat-product','SCENARIO','HARD','销售承诺客户两周内交付一个未评估的大功能，产品负责人首先应？','["立即答应并要求研发加班","澄清客户问题和合同影响，联合研发评估方案、风险与可分阶段交付范围","公开指责销售","不通知任何人"]','["澄清客户问题和合同影响，联合研发评估方案、风险与可分阶段交付范围"]','先同步事实和约束，再围绕客户价值给出经过评估的范围、时间和替代方案。','["跨部门协作","范围管理"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-prod-08','cat-product','MULTIPLE','MEDIUM','一份可执行的需求说明通常需要明确？','["目标和非目标","用户场景与流程","验收标准","数据口径和异常边界","只写一句做得好看"]','["目标和非目标","用户场景与流程","验收标准","数据口径和异常边界"]','可执行需求要让团队理解为什么做、为谁做、做到什么程度，以及异常和数据如何判断。','["PRD","验收"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-prod-09','cat-product','SINGLE','MEDIUM','分析“日活下降”时，第一步更合理的是？','["立刻改版","确认指标口径、时间范围和数据质量，再按渠道、版本、人群拆分","停止所有投放","只访谈一个用户"]','["确认指标口径、时间范围和数据质量，再按渠道、版本、人群拆分"]','先确认现象真实且口径一致，再通过维度拆分定位变化来源，之后提出假设并验证。','["数据分析","问题定位"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-prod-10','cat-product','TRUE_FALSE','EASY','用户访谈中应尽量避免诱导性问题，并追问用户过去发生过的具体行为。','["正确","错误"]','["正确"]','具体历史行为通常比抽象意愿更可靠，非诱导提问能减少访谈者将答案带向预设结论。','["用户研究","访谈"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),

('q-ai-04','cat-ai','SINGLE','MEDIUM','在语义检索系统中，Embedding 的主要作用是？','["把内容映射为可比较的向量表示","替代所有业务数据库","自动保证答案绝对正确","压缩图片文件"]','["把内容映射为可比较的向量表示"]','向量表示用于衡量语义相似性，但召回质量仍受切分、模型、索引和查询策略影响。','["Embedding","检索"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-ai-05','cat-ai','MULTIPLE','HARD','防御提示注入时可以采用哪些措施？','["隔离系统指令与不可信内容","限制模型可调用工具和权限","对输出执行结构与策略校验","把用户内容直接拼入最高权限指令","对高风险动作要求二次确认"]','["隔离系统指令与不可信内容","限制模型可调用工具和权限","对输出执行结构与策略校验","对高风险动作要求二次确认"]','提示注入无法仅靠一句提示彻底解决，需要权限最小化、输入隔离、输出验证和人工确认。','["提示注入","安全"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-ai-06','cat-ai','TRUE_FALSE','MEDIUM','把 temperature 设置为 0，就能保证模型每次输出完全一致且事实绝对正确。','["正确","错误"]','["错误"]','低温度降低随机性但不保证跨版本确定性，也不能消除知识错误、检索错误或提示歧义。','["生成参数","可靠性"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-ai-07','cat-ai','SCENARIO','HARD','上线的智能客服偶尔泄露内部知识库敏感字段，第一优先级措施是？','["增加回答字数","立即限制或关闭相关能力，确认影响并修复权限、检索过滤和输出审查","让模型自行道歉","忽略低频事件"]','["立即限制或关闭相关能力，确认影响并修复权限、检索过滤和输出审查"]','数据泄露事件先止损和评估影响，再从数据权限、检索边界、提示和输出策略建立多层修复。','["数据安全","事故响应"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-ai-08','cat-ai','MULTIPLE','MEDIUM','建立大模型应用评测集时应关注？','["覆盖真实高频任务","包含边界和对抗样本","定义可复现评分标准","按版本持续回归","只挑模型擅长的问题"]','["覆盖真实高频任务","包含边界和对抗样本","定义可复现评分标准","按版本持续回归"]','有效评测集需要代表性、难例、明确标准和持续回归，避免选择性展示。','["评测集","回归"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-ai-09','cat-ai','SINGLE','MEDIUM','企业知识频繁更新且需要引用来源时，通常优先考虑？','["只做一次微调","使用带权限过滤和引用的 RAG，并建立评测","把全部文档写进系统提示","要求用户自己查找"]','["使用带权限过滤和引用的 RAG，并建立评测"]','频繁变化的外部知识更适合可更新、可追溯的检索增强，微调更适合行为或风格学习。','["RAG","技术选型"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-ai-10','cat-ai','MULTIPLE','HARD','控制大模型应用成本可以采用？','["按任务路由不同模型","缓存可复用结果","限制上下文与输出长度","监控单请求和单用户成本","删除所有质量评测"]','["按任务路由不同模型","缓存可复用结果","限制上下文与输出长度","监控单请求和单用户成本"]','成本治理需要模型路由、上下文管理、缓存、配额和可观测性，同时维持质量门槛。','["成本治理","模型路由"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),

('q-scene-04','cat-scenario','SINGLE','MEDIUM','收到直接且合理的负面反馈时，较好的第一反应是？','["立即辩解","确认具体事实和影响，复述理解后讨论改进动作","攻击反馈者","退出项目"]','["确认具体事实和影响，复述理解后讨论改进动作"]','先理解反馈中的事实与期望，再说明背景、达成共识并落实可检查的改进行动。','["反馈","成长"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-scene-05','cat-scenario','MULTIPLE','MEDIUM','面对明显无法按原范围如期完成的项目，负责人应？','["尽早暴露风险","量化剩余工作和影响","提出减范围、分阶段或延期方案","继续承诺不变","明确新的负责人和检查点"]','["尽早暴露风险","量化剩余工作和影响","提出减范围、分阶段或延期方案","明确新的负责人和检查点"]','成熟的风险管理要求透明事实、提供取舍、更新责任与检查点，而不是隐藏问题。','["项目管理","沟通"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-scene-06','cat-scenario','TRUE_FALSE','EASY','复盘事故的主要目标是找到一个人承担全部责任。','["正确","错误"]','["错误"]','有效复盘关注事实、系统性原因、检测与防护改进，同时区分故意违规与正常的人为失误。','["复盘","团队文化"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-scene-07','cat-scenario','SCENARIO','HARD','客户线上业务因你的系统故障受到影响，沟通时首先应该？','["等完全修复后再说","及时确认已知影响、当前止损动作、下一更新时间，并持续同步","把责任推给供应商","只发送技术堆栈"]','["及时确认已知影响、当前止损动作、下一更新时间，并持续同步"]','危机沟通需要及时、准确、持续，明确影响、动作和下次更新时间，未知内容要标明仍在确认。','["客户沟通","事故"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-scene-08','cat-scenario','MULTIPLE','MEDIUM','推动没有直接汇报关系的跨团队项目时，有效方式包括？','["建立共同目标","明确决策人与责任边界","公开记录计划和依赖","只依赖私人关系","用数据和小步结果建立信任"]','["建立共同目标","明确决策人与责任边界","公开记录计划和依赖","用数据和小步结果建立信任"]','无职权影响力来自共同目标、透明机制、可靠交付和持续建立信任。','["影响力","跨团队"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-scene-09','cat-scenario','SINGLE','MEDIUM','团队成员连续出现同类交付问题，管理者更合理的做法是？','["在公开群里羞辱","基于具体事实进行一对一沟通，确认能力或资源原因并设定改进计划","永久忽略","直接替他完成所有工作"]','["基于具体事实进行一对一沟通，确认能力或资源原因并设定改进计划"]','管理沟通需要具体事实、原因诊断、支持措施、明确标准和后续检查，而不是贴标签。','["管理","绩效沟通"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP),
('q-scene-10','cat-scenario','SHORT_ANSWER','HARD','请写出处理模糊任务时最关键的四个动作关键词。','[]','["澄清目标","识别约束","拆解假设","验证反馈"]','面对模糊任务，应先澄清目标和成功标准，识别约束，拆解关键假设，再用小步验证获得反馈。','["模糊问题","问题解决"]','平台审核题库','2026.2',TRUE,CURRENT_TIMESTAMP);
